stepxmp.pre:
@font-face {
    font-family: "Noto Sans CJK JP";
    src: url("fonts/NotoSansCJKjp-Regular.otf");
}

@page {
    size: A5;
    margin: 15mm;
}

book {
    display: block;
    writing-mode: vertical-rl;
    font-family: "Noto Sans CJK JP";
    font-size: 11pt;
    line-height: 1.8;
}

p {
    display: block;
    margin-block-end: 1em;
    padding-inline-start: 1em;
    border-block-start: 0.5pt solid gray;
}

note {
    display: block;
    writing-mode: vertical-rl;
    height: 120pt;
}
